import heapq

def shortest_path(edges, start, end):
    # 1. マイナスの重みがあるかチェック
    for _, _, weight in edges:
        if weight < 0:
            raise ValueError("グラフに負の重み（negative weight）が含まれています。")

    # 2. start と end が同じ場合の処理
    if start == end:
        return (0, [start])

    # 3. 隣接リストの構築
    graph = {}
    for u, v, w in edges:
        if u not in graph:
            graph[u] = []
        graph[u].append((v, w))
        # グラフ内に孤立したノードがある場合に備えてto_nodeもキーとして登録しておく
        if v not in graph:
            graph[v] = []

    # start がグラフ内に存在しない場合
    if start not in graph:
        return (None, None)

    # 4. ダイクストラ法の初期化
    # 優先度付きキューには (current_distance, current_node, path) を格納
    pq = [(0, start, [start])]
    visited = set()

    while pq:
        current_distance, current_node, path = heapq.heappop(pq)

        # 目的地に到達した場合
        if current_node == end:
            return (current_distance, path)

        if current_node in visited:
            continue
        visited.add(current_node)

        # 隣接ノードを探索
        for neighbor, weight in graph.get(current_node, []):
            if neighbor not in visited:
                heapq.heappush(pq, (current_distance + weight, neighbor, path + [neighbor]))

    # 経路が存在しない場合
    return (None, None)

# --- 使用例 ---
if __name__ == "__main__":
    edges = [("A", "B", 1), ("B", "C", 2), ("A", "C", 5)]
    print(shortest_path(edges, "A", "C"))  # 出力: (3, ['A', 'B', 'C'])

    # 経路がない場合
    print(shortest_path(edges, "C", "A"))  # 出力: (None, None)

    # 同じノードの場合
    print(shortest_path(edges, "A", "A"))  # 出力: (0, ['A'])

    # 負の重みがある場合
    try:
        shortest_path([("A", "B", -1)], "A", "B")
    except ValueError as e:
        print(e)  # 出力: グラフに負の重み（negative weight）が含まれています。
